import re
from collections import namedtuple
from robot import get_version
from robot.result.model import Keyword as ResultKeyword
from robot.running.model import Keyword as RunningKeyword
from robot.utils.robottime import get_timestamp
from taf.ul.ettf.utils.exception import LibraryError


Version = namedtuple('Version', ['version_regex', 'class_type'])


class RobotframeworkVersionError(LibraryError):
    pass


class ResultKeyword(ResultKeyword):
    # source: lib/python3.6/site-packages/robot/output/listenerarguments.py
    # keyword start args ('doc', 'assign', 'tags', 'lineno', 'source', 'type', 'status', 'starttime')
    # keyword end args ('doc', 'assign', 'tags', 'lineno', 'source', 'type', 'status', 'starttime', 'endtime', 'elapsedtime')
    result = None
    lineno = 0
    source = None


class Robot3Api(object):
    @staticmethod
    def retrieve_teardown(obj):
        teardown = obj.keywords.teardown
        if teardown:
            return teardown.deepcopy()
        return None

    @staticmethod
    def replace_teardown(obj, new_teardown_name):
        obj.keywords.create(new_teardown_name, type='teardown')

    @staticmethod
    def create_model_keyword(name):
        return ResultKeyword(kwname=name, args=(), starttime=get_timestamp())


class Robot4Api(Robot3Api):
    @staticmethod
    def retrieve_teardown(obj):
        teardown = obj.teardown
        if teardown:
            return teardown.deepcopy()
        return None

    @staticmethod
    def replace_teardown(obj, new_teardown_name):
        obj.teardown = RunningKeyword(name=new_teardown_name, type='TEARDOWN')

    @staticmethod
    def create_model_keyword(name):
        from robot.result.model import BodyItem
        return ResultKeyword(kwname=name, args=(), starttime=get_timestamp(), type=BodyItem.KEYWORD)


class Robot5Api(Robot4Api):
    pass


class Robot6Api(Robot5Api):
    pass


def _get_api_based_on_robot_version():
    versions = [
        Version('^3.*', Robot3Api),
        Version('^4.*', Robot4Api),
        Version('^5.*', Robot5Api),
        Version('^6.*', Robot6Api),
    ]
    for version in versions:
        if re.match(version.version_regex, get_version()):
            return version.class_type
    raise RobotframeworkVersionError('Unsupported robotframework version', 'Installed version: {}. Supported: {}'.format(
        get_version(),
        ', '.join([v.version_regex[1:] for v in versions])))


def RobotApi():
    return _get_api_based_on_robot_version()
